package app.velyntora.windows.document;
import javax.swing.*;
import java.awt.*;
/** Android document dimension options: presets, proportional scale, interpolation and 9 anchors. */
public final class DimensionsDialog extends JPanel {
 public record Options(int width,int height,boolean bilinear,int anchor){}
 private final JSpinner width,height,percent=new JSpinner(new SpinnerNumberModel(100.,.01,600000.,1.));private final JCheckBox ratio=new JCheckBox("Mantener proporciones",true);private boolean syncing,valid=true;
 private final JComboBox<String> method=new JComboBox<>(new String[]{"Píxel cercano (pixel art)","Bilineal (suave)"});private final JComboBox<String> anchor=new JComboBox<>(new String[]{"Arriba izquierda","Arriba centro","Arriba derecha","Centro izquierda","Centro","Centro derecha","Abajo izquierda","Abajo centro","Abajo derecha"});
 public DimensionsDialog(int w,int h,int mode){super(new GridLayout(0,2,6,6));width=new JSpinner(new SpinnerNumberModel(w,1,6000,1));height=new JSpinner(new SpinnerNumberModel(h,1,6000,1));add(new JLabel("Ancho (px)"));add(width);add(new JLabel("Alto (px)"));add(height);method.setSelectedIndex(1);anchor.setSelectedIndex(4);
  if(mode==1){add(ratio);add(new JLabel("Máximo: 6000 × 6000"));add(new JLabel("Escala uniforme (%)"));add(percent);add(new JLabel("Remuestreo"));add(method);width.addChangeListener(e->scale(w,h,0));height.addChangeListener(e->scale(w,h,1));percent.addChangeListener(e->scale(w,h,2));}
  else if(mode==2){add(new JLabel("Anclaje del contenido"));add(anchor);}else{JComboBox<String> presets=new JComboBox<>(new String[]{"Personalizado","512 × 512","1024 × 1024","1920 × 1080","1080 × 1920","2400 × 1000","2560 × 1600","3840 × 2160"});int[][] sizes={{w,h},{512,512},{1024,1024},{1920,1080},{1080,1920},{2400,1000},{2560,1600},{3840,2160}};presets.addActionListener(e->{int n=presets.getSelectedIndex();if(n>0){width.setValue(sizes[n][0]);height.setValue(sizes[n][1]);}});add(new JLabel("Tamaños rápidos"));add(presets);}
 }
 private void scale(int w,int h,int source){if(syncing)return;syncing=true;try{int nw=(int)width.getValue(),nh=(int)height.getValue();if(source==2){double factor=((Number)percent.getValue()).doubleValue()/100;nw=(int)Math.round(w*factor);nh=(int)Math.round(h*factor);}else if(ratio.isSelected()){if(source==0)nh=(int)Math.round((double)nw*h/w);else nw=(int)Math.round((double)nh*w/h);}valid=nw>=1&&nh>=1&&nw<=6000&&nh<=6000;if(valid){width.setValue(nw);height.setValue(nh);if(source!=2&&ratio.isSelected())percent.setValue(100.*nw/w);}}finally{syncing=false;}}
 public Options options(){try{width.commitEdit();height.commitEdit();}catch(java.text.ParseException error){throw new IllegalArgumentException("Dimensiones no válidas",error);}if(!valid)throw new IllegalArgumentException("La escala calculada supera 6000 px o es menor que 1 px");int w=(int)width.getValue(),h=(int)height.getValue();if(w<1||h<1||w>6000||h>6000)throw new IllegalArgumentException("Usa entre 1 y 6000 px por lado");return new Options(w,h,method.getSelectedIndex()==1,anchor.getSelectedIndex());}
 public static Options show(Component owner,int w,int h,int mode){DimensionsDialog panel=new DimensionsDialog(w,h,mode);while(JOptionPane.showConfirmDialog(owner,panel,mode==0?"Crear ilustración":mode==1?"Tamaño de imagen":"Tamaño del lienzo",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){try{return panel.options();}catch(IllegalArgumentException error){JOptionPane.showMessageDialog(owner,error.getMessage());}}return null;}
}
